import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
page.setDefaultTimeout(20000);
const logs = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') logs.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
const resp = await page.goto('http://localhost:3000/', { waitUntil: 'load' });
console.log('status', resp.status());
await page.waitForFunction(() => window.__nova && window.__nova.state.ready, null, { timeout: 30000 });
console.log('ready info', await page.evaluate(() => window.__nova.info()));
await page.screenshot({ path: join(out, 'title.jpg'), type: 'jpeg', quality: 82 });
await page.locator('#startBtn').click();
await page.waitForTimeout(1200);
console.log('after start', await page.evaluate(() => window.__nova.info()));
await page.screenshot({ path: join(out, 'day.jpg'), type: 'jpeg', quality: 82 });
console.log('scroll', await page.evaluate(() => ({ sh: document.documentElement.scrollHeight, ih: innerHeight, sy: scrollY, bodyOverflow: getComputedStyle(document.body).overflow, pos: getComputedStyle(document.body).position })));
console.log('logs', logs);
await browser.close();

