export function drawPlayer(ctx, p, time, night = 0) {
  const walking = p.moving ? 1 : 0;
  const bob = walking ? Math.sin(time * 11.5) * 1.5 : Math.sin(time * 2.1) * 0.55;
  const dir = p.dir;
  const step = walking ? Math.sin(time * 11.5) * 3.1 : 0;

  // shadow
  ctx.fillStyle = 'rgba(16,34,26,.28)';
  ctx.beginPath();
  ctx.ellipse(p.x + 1.5, p.y + 8, 11.5, 4.8, 0, 0, TAU);
  ctx.fill();

  if (night > 0.2) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(p.x, p.y, 2, p.x, p.y, 34);
    g.addColorStop(0, `rgba(255,214,150,${0.1 * night})`);
    g.addColorStop(1, 'rgba(255,200,130,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(p.x, p.y, 34, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  ctx.save();
  ctx.translate(p.x, p.y + bob);
  ctx.rotate(dir);

  // feet
  ctx.fillStyle = '#3a4d3d';
  ctx.beginPath();
  ctx.ellipse(0, 8 + step * 0.35, 3.1, 2.1, 0, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(0, -8 - step * 0.35, 3.1, 2.1, 0, 0, TAU);
  ctx.fill();

  // scarf tail
  ctx.fillStyle = '#bd745a';
  ctx.beginPath();
  ctx.moveTo(-5, -3.4);
  ctx.quadraticCurveTo(-12 - Math.sin(time * 9) * 1.2, -1.2, -9.5, 2.6);
  ctx.quadraticCurveTo(-7.5, 0.2, -5, 1.2);
  ctx.closePath();
  ctx.fill();

  // backpack
  ctx.fillStyle = '#85633f';
  roundRect(ctx, -11.5, -5.6, 6.4, 11.2, 3.1);
  ctx.fill();
  ctx.fillStyle = '#6e5034';
  roundRect(ctx, -11.5, -5.6, 2.3, 11.2, 1.1);
  ctx.fill();

  // cloak
  const cloak = ctx.createRadialGradient(-2, -3, 1, 0, 0, 13);
  cloak.addColorStop(0, '#f7efdb');
  cloak.addColorStop(0.7, '#e9dec4');
  cloak.addColorStop(1, '#d4c6a6');
  ctx.fillStyle = cloak;
  ctx.beginPath();
  ctx.ellipse(0, 0, 10.2, 11.2, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(74,92,70,.55)';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // hood collar
  ctx.strokeStyle = 'rgba(75,101,77,.7)';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.arc(0.5, 0, 8.4, -1.15, 1.15);
  ctx.stroke();

  // hands
  ctx.fillStyle = '#e8c7a2';
  ctx.beginPath();
  ctx.arc(4.5, 8.6, 2.1, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(4.5, -8.6, 2.1, 0, TAU);
  ctx.fill();

  // head
  ctx.fillStyle = '#4a382c';
  ctx.beginPath();
  ctx.arc(2.4, 0, 6, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#eac9a4';
  ctx.beginPath();
  ctx.arc(4.5, 0, 3.7, -1.25, 1.25);
  ctx.closePath();
  ctx.fill();

  // hood highlight
  ctx.strokeStyle = 'rgba(246,239,218,.45)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(2.4, 0, 6, -2.6, -1.5);
  ctx.stroke();

  // scarf knot at the front
  ctx.fillStyle = '#c97a5e';
  ctx.beginPath();
  ctx.ellipse(6.7, 0, 2.6, 3.2, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(246,210,180,.4)';
  ctx.beginPath();
  ctx.ellipse(6.4, -0.7, 1, 1.2, 0, 0, TAU);
  ctx.fill();

  ctx.restore();
}

