651: function spawnAmbientLeaf() {
652:   if (!world) return;
653:   const view = {
654:     x1: state.cam.x - vw / (2 * zoom) - 30,
655:     x2: state.cam.x + vw / (2 * zoom) + 30,
656:     y1: state.cam.y - vh / (2 * zoom) - 30,
657:     y2: state.cam.y + vh / (2 * zoom) + 30,
658:   };
659:   const trees = world.objects.filter((o) => o.kind === 'tree' && o.ready && o.x > view.x1 && o.x < view.x2 && o.y > view.y1 && o.y < view.y2);
660:   if (!trees.length) return;
661:   const t = trees[(Math.random() * trees.length) | 0];
662:   state.particles.push({
663:     x: t.x + (Math.random() - 0.5) * 34,
664:     y: t.y + (Math.random() - 0.5) * 28,
665:     vx: 6 + Math.random() * 14,
666:     vy: 8 + Math.random() * 14,
667:     life: 2.6 + Math.random() * 2.6,
668:     maxLife: 5.2,
669:     size: 1.3 + Math.random() * 1.5,
670:     color: Math.random() > 0.55 ? '#809b58' : Math.random() > 0.5 ? '#b08d5a' : '#6c8b50',
671:     shape: 'leaf',
672:     rot: Math.random() * TAU,
673:     spin: (Math.random() - 0.5) * 4,
674:     alpha: 0.5,
675:     drag: 0.15,
676:   });
