746: function findTarget() {
747:   const p = state.player;
748:   let best = null;
749:   let bestD = Infinity;
750:   for (const o of world.objects) {
751:     if (!o.ready) continue;
752:     const reach = RESOURCE_META[o.kind].reach;
753:     const dx = o.x - p.x;
754:     const dy = o.y - p.y;
755:     const d2 = dx * dx + dy * dy;
756:     if (d2 < reach * reach && d2 < bestD) {
757:       best = o;
758:       bestD = d2;
759:     }
760:   }
761:   return best;
762: }
763: 
764: function resolveCollisions() {
765:   const p = state.player;
766:   for (let pass = 0; pass < 2; pass++) {
767:     for (const o of world.objects) {
768:       const meta = RESOURCE_META[o.kind];
769:       const dx = p.x - o.x;
770:       const dy = p.y - o.y;
771:       const rr = meta.radius * o.scale * 0.72 + 8;
772:       const d2 = dx * dx + dy * dy;
773:       if (d2 > 0.001 && d2 < rr * rr) {
774:         const d = Math.sqrt(d2);
775:         p.x = o.x + (dx / d) * rr;
776:         p.y = o.y + (dy / d) * rr;
777:       }
778:     }
779:     for (const f of world.fires) {
780:       const dx = p.x - f.x;
781:       const dy = p.y - f.y;
782:       const rr = 17;
783:       const d2 = dx * dx + dy * dy;
784:       if (d2 > 0.001 && d2 < rr * rr) {
785:         const d = Math.sqrt(d2);
786:         p.x = f.x + (dx / d) * rr;
787:         p.y = f.y + (dy / d) * rr;
788:       }
789:     }
790:   }
791: }
