793: function completeGather(o) {
794:   const meta = RESOURCE_META[o.kind];
795:   const tooled = (o.kind === 'tree' && state.tools.axe) || (o.kind === 'rock' && state.tools.pick);
796:   const amount = tooled ? 2 : 1;
797:   state.inventory[meta.resource] += amount;
798:   o.hits -= 1;
799:   if (o.hits <= 0) {
800:     o.ready = false;
801:     o.hits = meta.hits;
802:     o.respawnAt = state.elapsed + meta.respawn;
803:     o.growth = 0;
804:   }
805:   state.survival.stamina = Math.max(0, state.survival.stamina - 3.5);
806:   spawnHarvestBurst(o, meta.resource);
807:   if (o.kind === 'tree') sound.chop();
808:   else if (o.kind === 'rock') sound.mine();
809:   else sound.pick();
810:   haptic(7);
811:   addFloater(`+${amount} ${meta.resourceName}`, o.x, o.y - 28, '#f3e2b3');
812:   if (meta.resource === 'food' && !state.hints.food) {
813:     state.hints.food = true;
814:     showToast('Tap the berry count in the corner to eat.', 3200);
815:   }
816:   updateHud(true);
817: }
818: 
819: function update(dt) {
820:   if (!state.started || state.fainting) return;
821:   state.elapsed += dt;
822:   state.time += dt / DAY_LENGTH;
823:   if (state.time >= 1) {
824:     state.time -= 1;
825:     state.day++;
826:   }
827:   state.daylight = clamp(0.5 + 1.15 * Math.sin(state.time * TAU), 0, 1);
828:   const darkness = 1 - state.daylight;
829: 
830:   if (darkness > 0.55 && !nightNotified) {
831:     nightNotified = true;
832:     showToast('Night falls. Stay near a campfire to keep your sight.', 3800);
833:   } else if (darkness < 0.25 && nightNotified) {
834:     nightNotified = false;
835:     showToast('Morning returns to Nova Island.', 2400);
836:   }
837: 
838:   const p = state.player;
839:   let ix = stick.x;
840:   let iy = stick.y;
841:   if (keys.has('a') || keys.has('arrowleft')) ix -= 1;
842:   if (keys.has('d') || keys.has('arrowright')) ix += 1;
843:   if (keys.has('w') || keys.has('arrowup')) iy -= 1;
844:   if (keys.has('s') || keys.has('arrowdown')) iy += 1;
845:   let mag = Math.hypot(ix, iy);
846:   if (mag > 1) { ix /= mag; iy /= mag; mag = 1; }
847:   if (mag < 0.1) { ix = 0; iy = 0; mag = 0; }
848: 
849:   const gathering = state.actionHeld && state.target && !state.uiOpen;
850:   const moving = mag > 0.08 && !state.uiOpen && !gathering;
851:   p.moving = moving;
852: 
853:   if (moving) {
854:     const speed = 170 * (state.survival.stamina <= 0 ? 0.58 : 1);
855:     p.x += ix * speed * dt;
856:     p.y += iy * speed * dt;
857:     p.dir = Math.atan2(iy, ix);
858:     if (!state.hints.moved && state.started) state.hints.moved = true;
859:   }
860:   resolveCollisions();
861:   p.x = clamp(p.x, 30, WORLD - 30);
862:   p.y = clamp(p.y, 30, WORLD - 30);
863: 
864:   const fireDist = distanceToFire(p.x, p.y);
865:   state.nearFire = fireDist < 240;
866: 
867:   let staminaDrain = 0;
868:   if (moving) staminaDrain += 0.9;
869:   if (gathering) staminaDrain += 1.8;
870:   if (staminaDrain > 0) {
871:     state.survival.stamina = Math.max(0, state.survival.stamina - staminaDrain * dt);
872:   } else {
873:     state.survival.stamina = Math.min(100, state.survival.stamina + (state.nearFire ? 8.5 : 5.2) * dt);
874:   }
875: 
876:   state.survival.hunger = Math.max(0, state.survival.hunger - 0.2 * dt);
877:   if (state.survival.hunger <= 0) {
878:     state.survival.health = Math.max(0, state.survival.health - 0.68 * dt);
879:   } else if (state.survival.health < 100) {
880:     state.survival.health = Math.min(100, state.survival.health + (state.nearFire ? 0.24 : 0.055) * dt);
881:   }
882:   if (state.survival.hunger < 24 && !state.hints.hunger) {
883:     state.hints.hunger = true;
884:     showToast('You are getting hungry. Berries will help.', 3000);
885:   }
886:   if (state.survival.stamina <= 0 && !state.hints.stamina) {
887:     state.hints.stamina = true;
888:     showToast('You are spent. Stand still to catch your breath.', 2800);
889:   }
890:   if (state.survival.health <= 0) {
891:     faint();
892:     return;
893:   }
894: 
895:   state.target = state.uiOpen ? null : findTarget();
896:   if (state.target && gathering) {
897:     if (state.gather.targetId !== state.target.id) {
898:       state.gather.targetId = state.target.id;
899:       state.gather.progress = 0;
900:     }
901:     if (state.survival.stamina <= 0.5) {
902:       state.gather.progress = Math.max(0, state.gather.progress - dt * 3);
903:     } else {
904:       const dur = gatherDuration(state.target);
905:       state.gather.progress += dt / dur;
906:       state.gather.particleTimer -= dt;
907:       if (state.gather.particleTimer <= 0) {
908:         state.gather.particleTimer = 0.16;
909:         spawnHarvestBurst(state.target, RESOURCE_META[state.target.kind].resource);
910:       }
911:       if (state.gather.progress >= 1) {
912:         state.gather.progress = 0;
913:         completeGather(state.target);
914:       }
915:     }
916:   } else {
917:     state.gather.progress = Math.max(0, state.gather.progress - dt * 2.4);
918:     if (!state.actionHeld) state.gather.targetId = 0;
919:   }
920: 
921:   for (const o of world.objects) {
922:     if (!o.ready && state.elapsed >= o.respawnAt) {
923:       o.ready = true;
924:       o.hits = o.maxHits;
925:       o.growth = 0;
926:     }
927:     if (o.ready && o.growth < 1) o.growth = Math.min(1, o.growth + dt * 0.9);
928:   }
929: 
930:   updateParticles(dt);
931:   updateFireflies(dt);
932:   updateButterflies(dt, state.elapsed);
933: 
934:   leafTimer -= dt;
935:   if (leafTimer <= 0) {
936:     leafTimer = 0.9 + Math.random() * 2.4;
937:     spawnAmbientLeaf();
938:   }
939:   emberTimer -= dt;
940:   if (emberTimer <= 0) {
941:     emberTimer = 0.16 + Math.random() * 0.2;
942:     for (const f of world.fires) {
943:       if (Math.abs(f.x - p.x) < vw / zoom + 200 && Math.abs(f.y - p.y) < vh / zoom + 200) spawnEmber(f);
944:     }
945:   }
946: 
947:   const camLerp = 1 - Math.exp(-dt * 5.5);
948:   const hw = vw / (2 * zoom);
949:   const hh = vh / (2 * zoom);
950:   const tx = WORLD > hw * 2 ? clamp(p.x, hw, WORLD - hw) : WORLD / 2;
951:   const ty = WORLD > hh * 2 ? clamp(p.y, hh, WORLD - hh) : WORLD / 2;
952:   state.cam.x = lerp(state.cam.x, tx, camLerp);
953:   state.cam.y = lerp(state.cam.y, ty, camLerp);
954: 
955:   sound.update(dt, { daylight: state.daylight, moving, nearFire: state.nearFire });
956: 
957:   hudAccum += dt;
958:   if (hudAccum > 0.1) {
959:     hudAccum = 0;
960:     updateHud();
961:   }
962:   if (state.uiOpen) {
963:     craftAccum += dt;
964:     if (craftAccum > 0.3) {
965:       craftAccum = 0;
966:       updateCraftUI();
967:     }
968:   }
969: }
