async function gather(kind, label) {
  const target = await page.evaluate((k) => window.__nova.near(k), kind);
  await page.waitForTimeout(350);
  const hasTarget = await page.evaluate(() => !!window.__nova.state.target);
  if (!hasTarget) { ok(`${label} target acquired`, false); return; }
  const invBefore = await page.evaluate(() => ({ ...window.__nova.info().inventory }));
  const btn = await page.locator('#actionBtn').boundingBox();
  await page.mouse.move(btn.x + btn.width / 2, btn.y + btn.height / 2);
  await page.mouse.down();
  await page.waitForTimeout(4200);
  await page.mouse.up();
  await page.waitForTimeout(300);
  const invAfter = await page.evaluate(() => ({ ...window.__nova.info().inventory }));
  const res = kind === 'tree' ? 'wood' : kind === 'rock' ? 'stone' : 'food';
  const gained = invAfter[res] - invBefore[res];
  ok(`${label} gather yields ${res}`, gained > 0, `+${gained} (${invBefore[res]}→${invAfter[res]})`);
  return { invBefore, invAfter };
}

