import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 800, height: 800 } });
async function crop(src, sx, sy, sw, sh, out, scale = 2) {
  await page.goto('http://localhost:3000/screenshots/' + src);
  await page.evaluate(({ sx, sy, sw, sh, scale }) => {
    document.body.style.margin = '0';
    document.body.style.background = '#000';
    const img = document.querySelector('img');
    const c = document.createElement('canvas');
    c.width = sw * scale; c.height = sh * scale;
    const x = c.getContext('2d');
    x.imageSmoothingEnabled = false;
    x.drawImage(img, sx, sy, sw, sh, 0, 0, c.width, c.height);
    img.replaceWith(c);
  }, { sx, sy, sw, sh, scale });
  await page.waitForTimeout(150);
  await page.screenshot({ path: out });
}
