const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ ...devices['iPhone 15'], viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const page = await context.newPage();
const errs = [];
page.on('pageerror', (e) => errs.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });

const t0 = Date.now();
await page.goto('http://localhost:3000/?seed=777', { waitUntil: 'load' });
const loadMs = Date.now() - t0;
await page.waitForFunction(() => window.__nova && window.__nova.state.ready, null, { timeout: 30000 });
const readyMs = Date.now() - t0;
await page.click('#startBtn');
await page.waitForTimeout(600);
const fps = await page.evaluate(() => new Promise((resolve) => {
  let n = 0;
  const start = performance.now();
  function frame() {
    n++;
    if (performance.now() - start < 2000) requestAnimationFrame(frame);
    else resolve(n / ((performance.now() - start) / 1000));
  }
  requestAnimationFrame(frame);
}));
console.log(JSON.stringify({ loadMs, readyMs, fps: Math.round(fps) }));

// landscape
await page.setViewportSize({ width: 844, height: 390 });
await page.waitForTimeout(700);
await page.evaluate(() => { document.querySelectorAll('.toast').forEach((t) => t.remove()); window.__nova.setDay(); });
await page.waitForTimeout(400);
const land = await page.evaluate(() => ({
  iw: innerWidth, ih: innerHeight,
  sh: document.documentElement.scrollHeight,
  sw: document.documentElement.scrollWidth,
  info: window.__nova.info(),
}));
console.log(JSON.stringify({ landscape: { iw: land.iw, ih: land.ih, sh: land.sh, sw: land.sw, viewport: land.info.viewport, zoom: land.info.zoom } }));
await page.screenshot({ path: '/tmp/opencode/v-landscape.png' });
await page.evaluate(() => window.__nova.give(20, 20, 5));
await page.click('#craftBtn');
await page.waitForTimeout(600);
const sheetBox = await page.locator('#sheet').boundingBox();
console.log(JSON.stringify({ sheetBox }));
await page.screenshot({ path: '/tmp/opencode/v-landscape-craft.png' });
console.log(errs.length ? JSON.stringify(errs) : 'no errors');
await browser.close();

