export function drawWater(ctx, water, view, time) {
  const { sparkles, waterLines, shoreRipples } = water;
  // water lines
  ctx.save();
  for (const w of waterLines) {
    if (outside) continue;
    const pulse = 0.45 + 0.55 * Math.sin(time * w.speed + w.phase);
    ctx.globalAlpha = w.a * (0.35 + pulse * 0.65);
    ctx.strokeStyle = 'rgba(205,236,226,1)';
    ctx.lineWidth = 0.8;
    const dx = Math.sin(time * 0.35 + w.phase) * 2.2;
    ctx.beginPath();
    ctx.moveTo(w.x - w.len/2 + dx, w.y);
    ctx.quadraticCurveTo(w.x + dx, w.y - 1.2 - w.tilt*2, w.x + w.len/2 + dx, w.y + w.tilt*2);
    ctx.stroke();
  }
  // shore ripples
  for (const r of shoreRipples) {
    if (outside) continue;
    const p = (time * r.speed + r.phase) % 1;
    const rad = r.r + p * 9;
    ctx.globalAlpha = r.a * (1 - p) * 1.4;
    ctx.strokeStyle = 'rgba(220,240,230,1)';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.ellipse(r.x, r.y, rad, rad * 0.4, 0, 0, TAU);
    ctx.stroke();
  }
  // sparkles (existing enhanced)
  ...
  ctx.restore();
}
```
