  ctx.fill();
  ctx.fillStyle = '#b58a5f';
  roundRect(ctx, -16.6, -4.4, 4.2, 8.8, 2.0);
  ctx.fill();
  ctx.strokeStyle = 'rgba(88,61,37,.55)';
  ctx.lineWidth = 0.85;
  for (const sy of [-2.1, 2.1]) {
    ctx.beginPath();
    ctx.moveTo(-16.2, sy);
    ctx.lineTo(-12.3, sy);
    ctx.stroke();
  }

  // scarf tail
  const scarfFlutter = Math.sin(time * 8.4) * 1.3;
  ctx.fillStyle = '#b96f56';
  ctx.beginPath();
  ctx.moveTo(-4.2, -4.8);
  ctx.quadraticCurveTo(-12.6, -7.6 - scarfFlutter * 0.35, -15.6, -1.2);
  ctx.quadraticCurveTo(-10.4, -2.1, -4.9, 2.3);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(238,177,144,.4)';
  ctx.beginPath();
  ctx.ellipse(-10.6, -2.6, 2.8, 0.95, -0.3, 0, TAU);
  ctx.fill();

  // moss cloak / shoulders
  const cloak = ctx.createRadialGradient(1.5, -3.8, 1, 0, 0, 14.5);
  cloak.addColorStop(0, '#8aa273');
  cloak.addColorStop(0.52, '#6b8a5b');
  cloak.addColorStop(1, '#476642');
  ctx.fillStyle = cloak;
  ctx.beginPath();
  ctx.ellipse(0.3, 0, 11.4, 12.8, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(33,55,33,.62)';
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // hem and cloth folds
  ctx.strokeStyle = 'rgba(236,224,194,.2)';
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.ellipse(0.3, 0.8, 10.3, 11.6, 0, Math.PI * 0.1, Math.PI * 0.9);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(38,62,39,.28)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-8.2, -2.4);
  ctx.quadraticCurveTo(-4.4, -6.2, -1.2, -9.2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-8.2, 2.4);
  ctx.quadraticCurveTo(-4.4, 6.2, -1.2, 9.2);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,247,220,.13)';
  ctx.beginPath();
  ctx.moveTo(-6.4, -5.2);
  ctx.quadraticCurveTo(-1.6, -8.2, 4.2, -7.2);
  ctx.stroke();

  // cream shoulder trim along the front
  ctx.strokeStyle = 'rgba(240,229,201,.52)';
  ctx.lineWidth = 1.7;
  ctx.beginPath();
  ctx.arc(0.5, 0, 9.9, -1.12, 1.12);
  ctx.stroke();

  // shoulder straps
  ctx.strokeStyle = 'rgba(94,66,42,.58)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-9.6, -5.5);
  ctx.quadraticCurveTo(-4.2, -8.2, 2.6, -7.3);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-9.6, 5.5);
  ctx.quadraticCurveTo(-4.2, 8.2, 2.6, 7.3);
  ctx.stroke();

  // belt pouch
  ctx.fillStyle = '#7d5c3b';
  roundRect(ctx, -5.8, 7.4, 4.8, 3.9, 1.6);
  ctx.fill();
  ctx.strokeStyle = 'rgba(80,55,33,.5)';
  ctx.lineWidth = 0.7;
  ctx.stroke();

  // arms and hands
  const handSwing = p.moving ? step * 0.52 : 0;
  for (const side of [-1, 1]) {
    const ax = 2.1 + handSwing * side;
    const ay = side * 10.4;
    ctx.fillStyle = '#6c8a5a';
    ctx.beginPath();
    ctx.ellipse(ax, ay, 4.2, 3.0, side * -0.38, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(40,63,40,.32)';
    ctx.lineWidth = 0.8;
    ctx.stroke();
    ctx.fillStyle = '#eac9a3';
    ctx.beginPath();
    ctx.arc(ax + 2.4, ay + side * 0.7, 2.05, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,240,214,.35)';
    ctx.beginPath();
    ctx.arc(ax + 2.9, ay + side * 0.2, 0.7, 0, TAU);
    ctx.fill();
  }

  // hat brim shadow on the shoulders
  ctx.fillStyle = 'rgba(24,40,26,.24)';
  ctx.beginPath();
  ctx.ellipse(2.8, 1.8, 9.6, 8.8, 0, 0, TAU);
  ctx.fill();
}

function drawPlayerHead(ctx, time, sway) {
  // straw hat
  ctx.save();
  ctx.translate(2.5, 0);
  ctx.rotate(sway);

  ctx.fillStyle = 'rgba(48,38,24,.2)';
  ctx.beginPath();
  ctx.ellipse(0.7, 1.6, 9.6, 9.2, 0, 0, TAU);
  ctx.fill();

  const brim = ctx.createRadialGradient(-2.8, -2.8, 1, 0, 0, 9.8);
  brim.addColorStop(0, '#f2dfb3');
  brim.addColorStop(0.6, '#dfc48f');
  brim.addColorStop(1, '#c3a26c');
  ctx.fillStyle = brim;
  ctx.beginPath();
  ctx.ellipse(0, 0, 9.7, 9.1, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(118,88,52,.55)';
  ctx.lineWidth = 1.15;
  ctx.stroke();

  // woven brim texture
  ctx.strokeStyle = 'rgba(146,112,68,.24)';
  ctx.lineWidth = 0.65;
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * 5.7, Math.sin(a) * 5.4);
    ctx.lineTo(Math.cos(a) * 9.1, Math.sin(a) * 8.5);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(255,246,218,.18)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.ellipse(0, 0, 8.4, 7.8, 0, 0, TAU);
  ctx.stroke();

  // crown
  const crown = ctx.createRadialGradient(-2.2, -2.2, 0.5, 0, 0, 6.2);
  crown.addColorStop(0, '#ecd6a4');
  crown.addColorStop(1, '#bd9c64');
  ctx.fillStyle = crown;
  ctx.beginPath();
  ctx.ellipse(-0.3, 0, 5.9, 5.4, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(118,88,52,.45)';
  ctx.lineWidth = 0.95;
  ctx.stroke();

  // terracotta hat band
  ctx.strokeStyle = '#b5745b';
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.arc(-0.3, 0, 5.2, 0.18, TAU - 0.3);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(247,216,180,.35)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.arc(-0.3, 0, 5.2, 3.45, 5.15);
  ctx.stroke();

  // leaf tucked into the band
  ctx.save();
  ctx.translate(4.9, -4.3);
  ctx.rotate(-0.6);
  ctx.fillStyle = '#6f8d52';
  ctx.beginPath();
  ctx.ellipse(0, 0, 3.2, 1.6, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(42,64,36,.55)';
  ctx.lineWidth = 0.65;
  ctx.beginPath();
  ctx.moveTo(-2.3, 0);
  ctx.lineTo(2.6, 0);
  ctx.stroke();
  ctx.restore();

  // tiny flower on the brim
  ctx.save();
  ctx.translate(5.4, 4.0);
  ctx.rotate(0.4);
  ctx.fillStyle = 'rgba(244,236,213,.9)';
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU;
    ctx.beginPath();
    ctx.arc(Math.cos(a) * 1.1, Math.sin(a) * 1.1, 0.75, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = '#d9b66e';
  ctx.beginPath();
  ctx.arc(0, 0, 0.6, 0, TAU);
  ctx.fill();
  ctx.restore();

  ctx.strokeStyle = 'rgba(255,247,224,.5)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.arc(0, 0, 8.9, -2.5, -0.8);
  ctx.stroke();
  ctx.restore();

  // hair peeking from under the brim
  ctx.fillStyle = '#5a4433';
  ctx.beginPath();
  ctx.ellipse(4.6, 0, 3.8, 4.4, 0, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(4.2, -3.6, 1.8, 1.4, -0.5, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(4.2, 3.6, 1.8, 1.4, 0.5, 0, TAU);
  ctx.fill();

  // face
  const skin = ctx.createRadialGradient(7.2, -1.4, 0.5, 6.4, 0, 4.6);
  skin.addColorStop(0, '#f6d9b4');
  skin.addColorStop(1, '#e7bd93');
  ctx.fillStyle = skin;
  ctx.beginPath();
  ctx.ellipse(6.4, 0, 4.0, 4.45, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(148,100,66,.35)';
  ctx.lineWidth = 0.75;
  ctx.stroke();

  // cheeks
  ctx.fillStyle = 'rgba(208,126,100,.3)';
  ctx.beginPath();
  ctx.arc(6.3, -2.8, 1.1, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(6.3, 2.8, 1.1, 0, TAU);
  ctx.fill();

  // eyes, highlights, nose
  ctx.fillStyle = '#463528';
  ctx.beginPath();
  ctx.arc(7.5, -1.55, 0.72, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(7.5, 1.55, 0.72, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,250,235,.9)';
  ctx.beginPath();
  ctx.arc(7.74, -1.78, 0.24, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(7.74, 1.32, 0.24, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(190,132,92,.8)';
  ctx.beginPath();
  ctx.arc(9.05, 0, 0.6, 0, TAU);
  ctx.fill();
}

function drawWading(ctx, p, time, wade, waterline) {
  const strength = clamp(wade, 0, 1);
  ctx.save();

  // soft underwater shadow
  ctx.fillStyle = `rgba(8,40,48,${0.16 * strength})`;
  ctx.beginPath();
  ctx.ellipse(p.x + 1.5, p.y + 8.5, 15.5, 7.2, 0, 0, TAU);
  ctx.fill();

  // foam at the waterline
  ctx.strokeStyle = `rgba(228,244,232,${0.18 + strength * 0.3})`;
  ctx.lineWidth = 1.35;
  ctx.beginPath();
  ctx.ellipse(p.x, waterline, 12.8, 4.2, 0, 0.06, Math.PI - 0.06);
  ctx.stroke();
  ctx.strokeStyle = `rgba(215,238,226,${0.12 + strength * 0.16})`;
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.ellipse(p.x, waterline + 1.8, 14.6, 5.0, 0, 0.16, Math.PI - 0.16);
  ctx.stroke();

  // drifting rings
  const pace = p.moving ? 1.5 : 0.7;
  for (let i = 0; i < 3; i++) {
    const t = (time * 0.34 * pace + i / 3 + (p.wadePhase || 0)) % 1;
    const r = 10 + t * 26;
    ctx.globalAlpha = (1 - t) * (0.1 + strength * 0.2);
    ctx.strokeStyle = 'rgba(222,243,232,1)';
    ctx.lineWidth = 0.9;
    ctx.beginPath();
    ctx.ellipse(p.x, p.y + 2.5, r, r * 0.4, 0, 0, TAU);
    ctx.stroke();
  }

  ctx.restore();
}

export function drawPlayer(ctx, p, time, night = 0, wade = 0) {
  const walking = p.moving;
  const wadeClamped = clamp(wade, 0, 1);
  const stride = 11.5 * (1 - wadeClamped * 0.3);
  const bob = walking ? Math.sin(time * stride) * 1.4 * (1 - wadeClamped * 0.45) : Math.sin(time * 2.1) * 0.5;
  const step = walking ? Math.sin(time * stride) * 3.2 : 0;
  const sway = walking ? Math.sin(time * stride) * 0.035 : Math.sin(time * 2.1) * 0.015;
  const sink = wadeClamped * 5.5;
  const waterline = p.y + 11 - wadeClamped * 14;

  // shadow / underwater silhouette
  if (wadeClamped > 0.02) {
    ctx.fillStyle = `rgba(16,34,26,${0.16 * (1 - wadeClamped * 0.5)})`;
    ctx.beginPath();
    ctx.ellipse(p.x + 1.5, p.y + 9.5, 13.5, 5.4, 0, 0, TAU);
    ctx.fill();
  } else {
    ctx.fillStyle = 'rgba(16,34,26,.3)';
    ctx.beginPath();
    ctx.ellipse(p.x + 1.5, p.y + 9.5, 13.5, 5.4, 0, 0, TAU);
    ctx.fill();
  }

  if (night > 0.2) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(p.x, p.y, 2, p.x, p.y, 42);
    g.addColorStop(0, `rgba(255,214,150,${0.12 * night})`);
    g.addColorStop(1, 'rgba(255,200,130,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(p.x, p.y, 42, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  // body, clipped at the waterline
  ctx.save();
  if (wadeClamped > 0.02) {
    ctx.beginPath();
    ctx.rect(p.x - 52, p.y - 80, 104, waterline - (p.y - 80));
    ctx.clip();
  }
  ctx.translate(p.x, p.y + bob + sink);
  ctx.rotate(p.dir);
  ctx.scale(1.08, 1.08);
  drawPlayerBody(ctx, p, time, step);
  ctx.restore();

  if (wadeClamped > 0.02) {
    drawWading(ctx, p, time, wadeClamped, waterline);
  }

  // head stays above the surface and sinks only slightly
  ctx.save();
  ctx.translate(p.x, p.y + bob + sink * 0.32);
  ctx.rotate(p.dir);
  ctx.scale(1.08, 1.08);
  drawPlayerHead(ctx, time, sway);
  ctx.restore();
}

