const findDepth = async (target) => page.evaluate((target) => {
  const w = window.__nova.world, p = w.pond;
  let best = null, bestErr = 1e9;
  for (let a = 0; a < Math.PI * 2; a += 0.15) {
    for (let r = 8; r < p.r * 1.4; r += 3) {
      const x = p.x + Math.cos(a) * r, y = p.y + Math.sin(a) * r;
      const e = w.heightAt(x, y);
      if (e >= 0.012) continue;
      const depth = Math.min(1, (0.012 - e) / 0.34) * 0.62;
      const err = Math.abs(depth - target);
      if (err < bestErr) { bestErr = err; best = { x, y, depth, e }; }
    }
  }
  return best;
}, target);
const shallow = await findDepth(0.28);
const deep = await findDepth(0.55);
console.log('shallow', JSON.stringify(shallow), 'deep', JSON.stringify(deep));
await page.evaluate(({x, y}) => window.__nova.teleport(x, y), shallow);
